def L(key):
    en, el = T[key]
    return f'<span class="en">{en}</span><span class="el">{el}</span>'


def img(name):
    w, h = shots[name]
    en, el = ALT[name]
    return f'<a href="shots/{name}.webp" target="_blank" rel="noopener"><img src="shots/{name}.webp" width="{w}" height="{h}" loading="lazy" alt="{en}" data-alt-en="{en}" data-alt-el="{el}"></a>'



def log_details(lang_idx):
    """The release history as collapsible items (like the FAQ): the newest one is shown in the summary line, all closed."""
    items = re.findall(r'<li><b>([^<]+)</b>(?: \(([^)]*)\))?:? ?(.*?)</li>', T['log'][lang_idx], flags=re.S)
    out = []
    for ver, date, body in items:
        label = f'v{ver}' + (f' &middot; {date}' if date else '')
        body = body[:1].upper() + body[1:]
        short = re.sub(r'<[^>]+>', '', body)
        short = (short[:70].rsplit(' ', 1)[0] + '...') if len(short) > 74 else short
        out.append(f'<details><summary>{label} <span style="font-weight:400;color:var(--muted);font-size:13px">- {short}</span></summary><div>{body}</div></details>')
    return ''.join(out)


template = (root / 'landing.template.html').read_text(encoding='utf-8')
html = re.sub(r'\{\{L:(\w+)\}\}', lambda m: L(m.group(1)), template)
html = html.replace('{{LOGD}}', '<div class="en">' + log_details(0) + '</div><div class="el">' + log_details(1) + '</div>')
html = re.sub(r'\{\{IMG:(\w+)\}\}', lambda m: img(m.group(1)), html)
html = (html.replace('{{VERSION}}', version).replace('{{SHA}}', sha).replace('{{ZIPNAME}}', zip_name)
            .replace('{{DL}}', DL).replace('{{STAMP}}', stamp))
assert '{{' not in html, re.findall(r'\{\{[^}]*\}\}', html)[:5]
(root / 'dist' / 'index.html').write_text(html, encoding='utf-8')
print('landing built', round(len(html.encode('utf-8')) / 1024), 'KB | version', version, '| stamp', stamp, '| sha', sha[:12])
